sql.where:
1=1

    and spu.P_Id=#{params.pId}


    and u.U_State=#{params.uState}


    and u.U_Type=#{params.uType}


    and u.C_ID=#{params.cId}


    and p.PL_ID = #{params.plId}


    and u.U_CreateTime between #{params.timeStart} and #{params.timeEnd}


    and u.U_Name like concat('%',#{params.uName},'%')


    and c.C_Name like concat('%',#{params.cName},'%')


    and u.U_Account like concat('%',#{params.uAccount},'%')


    and u.U_Code like concat('%',#{params.uCode},'%')


    and u.U_MTel like concat('%',#{params.uMtel},'%')

mapper.select:
select p.P_ID as pId, p.D_ID as dId, p.P_Name as pName, d.D_Name as dName, c.C_Name as cName, plv.PL_Name as plName, pu.Pu_Id as puId, pu.PU_Sort as puSort, pu.PU_Main_Duty as puMainDuty, pu.Pu_Duty as puDuty, pu.Pu_Main_Dep as puMainDep,
from SYS_User u left join SYS_Position_User pu on u.U_ID=pu.U_ID left join SYS_Position p on pu.P_ID=p.P_ID left join SYS_Department d on d.D_ID=p.D_ID left join SYS_Company c on c.C_ID=u.C_ID left join SYS_PositionLV plv on plv.PL_ID=u.PL_ID where 1=1
order by plv.PL_Name ${params.sortType}
order by u.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by puSort ASC
order by u.U_CreateTime DESC

select u.* from SYS_User u left join SYS_Position_User_P pu on u.U_ID=pu.U_ID left join SYS_Position_P p on pu.PP_ID=p.PP_ID left join SYS_Department_P d on d.PD_ID=p.PD_ID where 1=1
and d.P_Id in
#{id}

SELECT p.P_ID AS pId, p.D_ID AS dId, p.P_Name AS pName, d.D_Name AS dName, c.C_Name AS cName, plv.PL_Name AS plName, pu.Pu_Id AS puId, pu.PU_Sort AS puSort, pu.PU_Main_Duty AS puMainDuty, pu.Pu_Duty AS puDuty, pu.Pu_Main_Dep AS puMainDep, u.U_ID AS uId, u.PL_ID AS plID, u.C_ID AS cID, u.U_Name AS uName, u.U_Code AS uCode, u.U_MTel AS uMtel, u.U_Tel AS uTel, u.U_Email AS uEmail, u.U_Account AS uAccount, u.U_PassWord AS uPassword, u.U_Sex AS uSex, u.U_Birthday AS uBirthday, u.U_State AS uState, u.U_MDM_NO AS uMdmNo, u.U_CreateTime AS uCreatetime, u.U_CreateU_ID AS uCreateuID, u.U_CreateU_Name AS uCreateuName, u.U_Type AS uType, u.U_Office AS uOffice, u.U_Cornet AS uCornet, u.U_IdCard AS uIdcard, u.U_Sort AS uSort, u.U_Push_Id AS uPushId, u.Open_Id AS openId, u.U_Signature AS uSignature, u.U_Qualification AS uQualification, u.sign AS sign, u.u_class AS uClass FROM SYS_User u LEFT JOIN SYS_Position_User pu ON u.U_ID = pu.U_ID LEFT JOIN SYS_Position p ON pu.P_ID = p.P_ID LEFT JOIN SYS_Department d ON d.D_ID = p.D_ID LEFT JOIN SYS_Company c ON c.C_ID = u.C_ID LEFT JOIN SYS_PositionLV plv ON plv.PL_ID = u.PL_ID WHERE u.U_State = 1
and d.D_Name in
#{dNames}
and p.P_Name in
#{pNames}
